dsl.css:
/* ============ 路书 · 全局设计令牌 ============ */
:root {
  --rb-primary: #1F6FEB;
  --rb-primary-soft: #E8F1FE;
  --rb-success: #18A058;
  --rb-warning: #F0A020;
  --rb-danger: #D03050;
  --rb-text: #1F2225;
  --rb-text-sub: #606266;
  --rb-text-faint: #8A9099;
  --rb-bg: #F7F8FA;
  --rb-surface: #FFFFFF;
  --rb-border: #E4E7ED;
  --rb-radius: 8px;
  --rb-radius-lg: 12px;
  --rb-shadow: 0 1px 3px rgba(20, 22, 26, 0.06);
  --rb-shadow-hover: 0 4px 14px rgba(20, 22, 26, 0.10);
}

.page {
  width: 390px;
  min-height: 844px;
  margin: 0 24px 24px 0;
  display: inline-block;
  vertical-align: top;
  background: var(--rb-bg);
  border: 1px solid var(--rb-border);
  border-radius: 16px;
  overflow: hidden;
  font-family: system-ui, "PingFang SC", "Microsoft YaHei", sans-serif;
  font-size: 14px;
  color: var(--rb-text);
  box-shadow: var(--rb-shadow);
}

/* 图表容器 */
.radar {
  width: 168px;
  height: 168px;
  margin: 8px auto 0;
  background: conic-gradient(#1F6FEB2E, #1F6FEB0A);
  border: 1px dashed #B9D2F7;
  border-radius: 50%;
}

/* 状态栏 + 导航栏 */
.navbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 44px;
  padding: 0 16px;
  background: var(--rb-surface);
  border-bottom: 1px solid var(--rb-border);
  font-size: 16px;
  font-weight: 600;
}
.nav-left, .nav-right { width: 48px; font-size: 12px; font-weight: 400; color: var(--rb-text-faint); }
.nav-right { text-align: right; }

/* 布局 */
.body { padding: 16px; }
.card {
  background: var(--rb-surface);
  border: 1px solid var(--rb-border);
  border-radius: var(--rb-radius-lg);
  padding: 16px;
  margin-bottom: 12px;
  box-shadow: var(--rb-shadow);
}
.card-flat { box-shadow: none; }
.section-head { margin: 16px 0 8px; }
.section-title { font-size: 15px; font-weight: 600; }
.section-extra { font-size: 12px; color: var(--rb-text-faint); }
.link-more { font-size: 12px; color: var(--rb-primary); }

/* 文字 */
.t-h1 { font-size: 22px; font-weight: 700; line-height: 1.3; }
.t-h2 { font-size: 17px; font-weight: 600; line-height: 1.4; }
.t-body { font-size: 14px; line-height: 1.7; color: var(--rb-text); }
.t-sub { font-size: 13px; line-height: 1.7; color: var(--rb-text-sub); }
.t-faint { font-size: 12px; color: var(--rb-text-faint); }
.t-num { font-size: 28px; font-weight: 700; letter-spacing: -0.5px; }
.t-strong { font-weight: 600; }

/* 标签 */
.tag {
  display: inline-block;
  padding: 2px 8px;
  font-size: 11px;
  line-height: 18px;
  border-radius: 4px;
  background: var(--rb-primary-soft);
  color: var(--rb-primary);
}
.tag-success { background: #E8F7EE; color: var(--rb-success); }
.tag-warning { background: #FDF3E2; color: var(--rb-warning); }
.tag-danger  { background: #FCEBEF; color: var(--rb-danger); }
.tag-plain   { background: #F0F1F3; color: var(--rb-text-sub); }

/* 按钮 */
.btn {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 44px;
  border-radius: var(--rb-radius);
  font-size: 15px;
  font-weight: 500;
  cursor: pointer;
}
.btn-primary { background: var(--rb-primary); color: #fff; }
.btn-ghost { background: var(--rb-surface); color: var(--rb-primary); border: 1px solid var(--rb-primary); }
.btn-plain { background: #F0F1F3; color: var(--rb-text-sub); }
.btn-disabled { background: #EDEFF2; color: #B4B9C1; }

/* 表单 */
.field { margin-bottom: 14px; }
.field-label { font-size: 13px; color: var(--rb-text-sub); margin-bottom: 6px; }
.input {
  height: 44px;
  padding: 0 12px;
  background: #FBFBFC;
  border: 1px solid var(--rb-border);
  border-radius: var(--rb-radius);
  font-size: 14px;
  color: var(--rb-text);
}
.input-ph { color: #B4B9C1; }
.textarea { height: 88px; padding: 10px 12px; align-items: flex-start; }

/* 进度条 */
.progress { height: 6px; background: #EDEFF2; border-radius: 3px; overflow: hidden; }
.progress-in { height: 6px; background: var(--rb-primary); border-radius: 3px; }

/* 列表 */
.list-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 0;
  border-bottom: 1px solid var(--rb-border);
}
.list-item:last-child { border-bottom: none; }

/* 空/错/载 三态 */
.empty {
  padding: 32px 16px;
  text-align: center;
  color: var(--rb-text-faint);
  font-size: 13px;
}
.skeleton { background: #EDEFF2; border-radius: 6px; height: 14px; margin-bottom: 8px; }

/* 提示条 */
.hint {
  display: flex;
  gap: 8px;
  padding: 10px 12px;
  background: #FFF8EC;
  border: 1px solid #F6E3BF;
  border-radius: var(--rb-radius);
  font-size: 12px;
  line-height: 1.6;
  color: #8A6D3B;
}
.hint-danger { background: #FCEBEF; border-color: #F3C6D1; color: #A32C46; }
.hint-info { background: var(--rb-primary-soft); border-color: #C9DCFB; color: #2A5599; }

/* 底部 TabBar */
.tabbar {
  display: flex;
  height: 56px;
  border-top: 1px solid var(--rb-border);
  background: var(--rb-surface);
}
.tab {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  font-size: 10px;
  color: var(--rb-text-faint);
}
.tab-on { color: var(--rb-primary); font-weight: 600; }
.tab-icon { font-size: 18px; line-height: 20px; }

/* 聊天 */
.bubble-user {
  align-self: flex-end;
  max-width: 280px;
  padding: 10px 14px;
  background: var(--rb-primary);
  color: #fff;
  border-radius: 12px 12px 2px 12px;
  font-size: 14px;
  line-height: 1.6;
}
.bubble-ai {
  align-self: flex-start;
  max-width: 300px;
  padding: 10px 14px;
  background: var(--rb-surface);
  border: 1px solid var(--rb-border);
  border-radius: 12px 12px 12px 2px;
  font-size: 14px;
  line-height: 1.7;
}
.cite {
  margin-top: 8px;
  padding: 8px 10px;
  background: #F7F9FC;
  border-left: 3px solid var(--rb-primary);
  border-radius: 4px;
  font-size: 12px;
  color: var(--rb-text-sub);
  line-height: 1.6;
}
.streaming::after { content: "▍"; color: var(--rb-primary); }

